<?php declare(strict_types=1); namespace Annam; $title='Orders & billing'; ?>
<div class="o-actions"><a class="o-btn o-btn-primary" href="/manage/orders/new/">+ Create booking</a></div><?php if(isset($groups)): ?><div class="o-actions"><a class="o-btn <?= empty($_GET['meal_group'])?'o-btn-primary':'' ?>" href="?">All orders</a><?php foreach($groups as $group=>$count): ?><a class="o-btn <?= ($_GET['meal_group']??'')===$group?'o-btn-primary':'' ?>" href="?<?= e(http_build_query(array_replace($_GET,['meal_group'=>$group]))) ?>"><?= e(implode(' + ',array_map('ucfirst',explode('+',$group)))) ?> (<?= e($count) ?>)</a><?php endforeach; ?></div><?php endif; ?><form class="o-filters"><input type="hidden" name="meal_group" value="<?= e($_GET['meal_group']??'') ?>"><select name="status"><option value="">All statuses</option><?php foreach(array_keys(Orders::FLOW) as $status): ?><option value="<?= e($status) ?>" <?= ($_GET['status']??'')===$status?'selected':'' ?>><?= e(ucfirst(str_replace('_',' ',$status))) ?></option><?php endforeach; ?></select><input name="q" placeholder="Search order, customer or phone" value="<?= e($_GET['q']??'') ?>"><select name="channel"><option value="">All channels</option><?php foreach(['web','manual','whatsapp'] as $channel): ?><option <?= ($_GET['channel']??'')===$channel?'selected':'' ?>><?= e($channel) ?></option><?php endforeach; ?></select><button class="o-btn">Search</button></form>
<div class="o-table-wrap"><table class="o-table"><thead><tr><th>Order</th><th>Customer</th><th>For</th><th>Total</th><th>Status</th><th>Payment</th></tr></thead><tbody><?php foreach($records as $record): ?><tr><td><a href="/manage/orders/<?= e($record['id']) ?>/"><strong><?= e($record['order_no']) ?></strong></a><small><?= e($record['channel'].' · '.$record['placed_at']) ?></small></td><td><?= e($record['customer_name']) ?><small><?= e($record['customer_phone']) ?></small></td><td><?= e($record['meal_label']??'') ?><small><?= e($record['delivery_date']??'') ?></small></td><td><?= money($record['total']) ?></td><td><?= e(str_replace('_',' ',$record['status'])) ?></td><td><?= e($record['payment_status']) ?></td></tr><?php endforeach; ?><?php if(!$records): ?><tr><td colspan="5">No orders yet.</td></tr><?php endif; ?></tbody></table></div>
<?php if(isset($page,$total)): ?><div class="o-actions"><p><?= e($total) ?> matching orders</p><?php foreach(array_unique(array_filter([1,$page-1,$page,$page+1,(int)ceil($total/50)],fn($n)=>$n>=1&&$n<=max(1,ceil($total/50)))) as $n): ?><a class="o-btn <?= $n===$page?'o-btn-primary':'' ?>" href="?<?= e(http_build_query(array_replace($_GET,['page'=>$n]))) ?>"><?= e($n) ?></a><?php endforeach; ?></div><?php endif; ?>